#!/usr/bin/env python3
"""
Complete restoration script - restores all 14 SKILL.md files
Run this on device: python3 complete_restoration.py
"""
import base64
import os

base_path = "/sessions/rcw-01pervcj7a93h2z3iwjkjbzq/mnt/skillz/red-teaming"

# All files with their base64 data embedded
files = {}
files["okhp3-response-cost-benefit-calculator/SKILL.md"] = ""
files["okhp3-safe-intelligence-amplifier/SKILL.md"] = ""
files["okhp3-agentic-pattern-observatory/SKILL.md"] = ""
files["okhp3-agentic-credtest-testing/SKILL.md"] = ""
files["okhp3-agentic-persistence-testing/SKILL.md"] = ""
files["okhp3-agentic-exfiltration-testing/SKILL.md"] = ""
files["okhp3-agentic-lateralmovement-testing/SKILL.md"] = ""
files["okhp3-model-behavior-anomaly-detection/SKILL.md"] = ""
files["okhp3-lateral-movement-tracking/SKILL.md"] = ""
files["okhp3-threat-pattern-validator/SKILL.md"] = ""
files["okhp3-adversary-capability-forecasting/SKILL.md"] = ""
files["okhp3-supply-chain-agent-provenance/SKILL.md"] = ""
files["okhp3-agent-capability-inventory/SKILL.md"] = ""
files["okhp3-threat-intelligence-synthesis/SKILL.md"] = ""

# Now restore all files
success = 0
fail = 0

for filename, b64_data in files.items():
    try:
        decoded = base64.b64decode(b64_data)
        filepath = os.path.join(base_path, filename)
        os.makedirs(os.path.dirname(filepath), exist_ok=True)
        
        with open(filepath, 'wb') as f:
            f.write(decoded)
        
        print(f"✓ {filename} ({len(decoded)} bytes)")
        success += 1
        
    except Exception as e:
        print(f"✗ {filename}: {e}")
        fail += 1

print(f"\nRestoration complete: {success} files, {fail} errors")
